async def handle_radios(target: "Frame") -> int:
    """
    Answer radio questions (work auth, sponsorship, etc.).

    Returns number of radio groups answered.
    """
    answered = 0
    try:
        radio_groups = await target.locator("fieldset").all()
        for group in radio_groups:
            label_el = group.locator("legend").first
            if await label_el.count() == 0:
                continue
            label = (await label_el.text_content() or "").lower()

            # Determine correct answer
            if any(w in label for w in ["authorized", "eligible", "legally"]):
                answer = "yes"
            elif any(w in label for w in ["sponsor", "visa", "require"]):
                answer = "no"
            else:
                continue

            # Click the matching radio option
            radios = await group.locator("input[type='radio']").all()
            for radio in radios:
                opt_label = (
                    await radio.evaluate("el => el.labels?.[0]?.textContent || ''")
                ).lower()
                if answer in opt_label:
                    await human_click_safe(None, await radio.element_handle())
                    await asyncio.sleep(gaussian_delay(0.2, 0.5))
                    answered += 1
                    break
    except Exception as e:
        logger.debug(f"IndeedApply radios: {e}")

    return answered
