                <input type="text" id="skill" class="combobox-input" 
                       placeholder="Select your primary skill..." 
                       autocomplete="off"
                       aria-autocomplete="list"
                       aria-activedescendant="">
            </div>
            <ul id="skill-listbox" role="listbox" class="combobox-listbox">
                <li role="option" data-value="python" class="combobox-option">Python</li>
                <li role="option" data-value="javascript" class="combobox-option">JavaScript</li>
                <li role="option" data-value="java" class="combobox-option">Java</li>
                <li role="option" data-value="cpp" class="combobox-option">C++</li>
                <li role="option" data-value="rust" class="combobox-option">Rust</li>
                <li role="option" data-value="go" class="combobox-option">Go</li>
                <li role="option" data-value="typescript" class="combobox-option">TypeScript</li>
                <li role="option" data-value="other" class="combobox-option">Other</li>
            </ul>
        </div>
    </div>

    <!-- Native Select for Experience -->
    <div class="form-group">
        <h2>Native Select Element</h2>
        <label for="experience">Years of Experience</label>
        <select id="experience" name="experience">
            <option value="">Select experience...</option>
            <option value="0-1">0-1 years</option>
            <option value="1-3">1-3 years</option>
            <option value="3-5">3-5 years</option>
            <option value="5-10">5-10 years</option>
            <option value="10+">10+ years</option>
        </select>
    </div>

    <script>
        // Minimal JavaScript to simulate React combobox behavior
        document.querySelectorAll('.combobox-input').forEach(input => {
            const wrapper = input.closest('.combobox-wrapper');
            const listbox = wrapper.querySelector('.combobox-listbox');
            const combobox = wrapper.querySelector('[role="combobox"]');
            const options = listbox.querySelectorAll('.combobox-option');
            let highlightedIndex = -1;

            // Toggle dropdown on focus/click
            input.addEventListener('focus', () => {
                openDropdown();
            });

            input.addEventListener('click', () => {
                if (!listbox.classList.contains('open')) {
                    openDropdown();
                }
            });

            // Close dropdown on blur (with delay for option clicks)
            input.addEventListener('blur', () => {
                setTimeout(() => closeDropdown(), 150);
            });

            // Handle keyboard navigation
            input.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (!listbox.classList.contains('open')) {
                        openDropdown();
                    }
                    highlightNext();
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    highlightPrev();
                } else if (e.key === 'Enter' && highlightedIndex >= 0) {
                    e.preventDefault();
                    selectHighlighted();
                } else if (e.key === 'Escape') {
                    closeDropdown();
                }
            });

            // Filter options on input
            input.addEventListener('input', () => {
                const search = input.value.toLowerCase();
                options.forEach(opt => {
                    const text = opt.textContent.toLowerCase();
                    opt.style.display = text.includes(search) ? '' : 'none';
                });
                if (!listbox.classList.contains('open')) {
                    openDropdown();
                }
            });

            // Click on option
            options.forEach((opt, idx) => {
                opt.addEventListener('click', () => {
                    selectOption(opt);
                    // Show "other" input if "Other" is selected
                    if (opt.dataset.value === 'other') {
                        const otherInput = wrapper.parentElement.querySelector('.other-input');
                        if (otherInput) {
                            otherInput.style.display = 'block';
                            otherInput.classList.add('visible');
                        }
                    }
                });

                opt.addEventListener('mouseenter', () => {
                    highlightIndex(idx);
                });
            });

            function openDropdown() {
                listbox.classList.add('open');
                combobox.setAttribute('aria-expanded', 'true');
                highlightedIndex = -1;
            }

            function closeDropdown() {
                listbox.classList.remove('open');
                combobox.setAttribute('aria-expanded', 'false');
                highlightedIndex = -1;
                options.forEach(opt => opt.classList.remove('highlighted'));
            }

            function highlightNext() {
                const visibleOpts = Array.from(options).filter(opt => opt.style.display !== 'none');
                if (visibleOpts.length === 0) return;
                highlightedIndex = Math.min(highlightedIndex + 1, visibleOpts.length - 1);
                highlightVisibleOption(visibleOpts);
            }

            function highlightPrev() {
                const visibleOpts = Array.from(options).filter(opt => opt.style.display !== 'none');
                if (visibleOpts.length === 0) return;
                highlightedIndex = Math.max(highlightedIndex - 1, 0);
                highlightVisibleOption(visibleOpts);
            }

            function highlightVisibleOption(visibleOpts) {
                options.forEach(opt => opt.classList.remove('highlighted'));
                if (highlightedIndex >= 0 && highlightedIndex < visibleOpts.length) {
                    visibleOpts[highlightedIndex].classList.add('highlighted');
                }
            }

            function highlightIndex(idx) {
                highlightedIndex = idx;
                options.forEach((opt, i) => {
                    opt.classList.toggle('highlighted', i === idx);
                });
            }

            function selectHighlighted() {
                const visibleOpts = Array.from(options).filter(opt => opt.style.display !== 'none');
                if (highlightedIndex >= 0 && highlightedIndex < visibleOpts.length) {
                    selectOption(visibleOpts[highlightedIndex]);
                }
            }

            function selectOption(opt) {
                input.value = opt.textContent;
                closeDropdown();
            }
        });
    </script>
</body>
